from PIL import Image, ImageDraw, ImageFont

im = Image.open('chess_board.png').convert('RGB')
px = im.load()
W={'K':0x2654,'Q':0x2655,'R':0x2656,'B':0x2657,'N':0x2658,'P':0x2659}
B={'k':0x265A,'q':0x265B,'r':0x265C,'b':0x265D,'n':0x265E,'p':0x265F}
fonts=['/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf','/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf']

def lum(r,g,b): return 0.299*r+0.587*g+0.114*b

def square_alpha(r,c,kind):
    # estimate bg by corner majority
    from collections import Counter
    cnt=Counter()
    for (yy,xx) in [(3,3),(3,76),(76,3),(76,76)]:
        for dy in range(4):
            for dx in range(4):
                cnt[px[c*80+xx+dx,r*80+yy+dy]]+=1
    bg=cnt.most_common(1)[0][0]
    bl=lum(*bg)
    out=Image.new('L',(80,80),0); o=out.load()
    for y in range(80):
        for x in range(80):
            l=lum(*px[c*80+x,r*80+y])
            if kind=='white':
                a=(l-bl)/(255.0-bl)
            else:
                a=(bl-l)/bl
            a=max(0.0,min(1.0,a))
            o[x,y]=int(a*255)
    return out,bg

def crop_resize(img,size=64):
    bb=img.getbbox()
    if not bb: return None,None
    g=img.crop(bb)
    return g.resize((size,size),Image.LANCZOS), bb

def render_ref(code,fontpath,size,pad=100):
    font=ImageFont.truetype(fontpath,size)
    img=Image.new('L',(size*3+pad,size*3+pad),0)
    d=ImageDraw.Draw(img)
    d.text((pad,pad),chr(code),fill=255,font=font)
    return img

# precompute refs normalized
import math
def arr(img,size=64):
    return list(img.getdata())
refs={}
for fp in fonts:
    for kind,DD in [('white',W),('black',B)]:
        for name,code in DD.items():
            img=render_ref(code,fp,220)
            g,bb=crop_resize(img)
            refs[(fp,kind,name)]=(g,bb)

def ncc(a,b):
    n=len(a); ma=sum(a)/n; mb=sum(b)/n
    va=sum((x-ma)**2 for x in a); vb=sum((x-mb)**2 for x in b)
    if va==0 or vb==0: return 0
    return sum((a[i]-ma)*(b[i]-mb) for i in range(n))/math.sqrt(va*vb)

occ=[]
for r in range(8):
    for c in range(8):
        # counts rough
        cntw=cntb=0
        for y in range(0,80,2):
            for x in range(0,80,2):
                R,G,Bv=px[c*80+x,r*80+y]
                if min(R,G,Bv)>245: cntw+=1
                if max(R,G,Bv)<80: cntb+=1
        if cntw>20 or cntb>20:
            occ.append((r,c,'white' if cntw>cntb else 'black'))

for r,c,kind in occ:
    sq,bg=square_alpha(r,c,kind)
    g,bb=crop_resize(sq)
    a=arr(g)
    scores=[]
    for (fp,k2,name),(rg,rbb) in refs.items():
        if k2!=kind: continue
        s=ncc(a,arr(rg))
        scores.append((s,name,fp.split('/')[-1].replace('DejaVuSans','Sans')))
    scores.sort(reverse=True)
    top=" | ".join(f"{n}:{s:.3f}:{f}" for s,n,f in scores[:3])
    print(f"r{r}c{c} {kind:5s} box={bb[2]-bb[0]}x{bb[3]-bb[1]} bg={bg} :: {top}")
