from PIL import Image, ImageDraw, ImageFont
from collections import Counter
im=Image.open('chess_board.png').convert('RGB'); px=im.load()
def lum(r,g,b): return .299*r+.587*g+.114*b
FONT='/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'
W={'K':0x2654,'Q':0x2655,'R':0x2656,'B':0x2657,'N':0x2658,'P':0x2659}
Bk={'k':0x265A,'q':0x265B,'r':0x265C,'b':0x265D,'n':0x265E,'p':0x265F}
def sq_alpha(r,c,kind):
    cnt=Counter()
    for yy,xx in [(3,3),(3,76),(76,3),(76,76)]:
        for dy in range(3):
            for dx in range(3): cnt[px[c*80+xx+dx,r*80+yy+dy]]+=1
    bg=cnt.most_common(1)[0][0]; bl=lum(*bg)
    out=[[0.0]*80 for _ in range(80)]
    for y in range(80):
        for x in range(80):
            l=lum(*px[c*80+x,r*80+y])
            a=(l-bl)/(255-bl) if kind=='white' else (bl-l)/bl
            out[y][x]=max(0.0,min(1.0,a))
    return out
def render(code,s):
    font=ImageFont.truetype(FONT,s)
    img=Image.new('L',(120,120),0); d=ImageDraw.Draw(img)
    d.text((60,60),chr(code),fill=255,font=font,anchor='mm')
    p=img.load()
    return [[p[x,y]/255.0 for x in range(120)] for y in range(120)]
def centroid(g,n):
    sx=sy=t=0.0
    for y in range(n):
        for x in range(n):
            v=g[y][x]; sx+=v*x; sy+=v*y; t+=v
    return (sx/t,sy/t) if t else (n/2,n/2)
refs={}
for s in range(46,64):
    for n,code in list(W.items())+list(Bk.items()):
        g=render(code,s)
        # crop 120 -> place into 80 centered by centroid later; keep
        refs[(s,n)]=g
def err(a,b,dx,dy):
    # b is 120x120 centered at 60, place at 40+dx,40+dy
    ox=60-40-dx; oy=60-40-dy
    tot=0.0;cnt=0
    for y in range(16,78):
        yy=y+oy
        if yy<0 or yy>=120: continue
        for x in range(12,68):
            xx=x+ox
            if xx<0 or xx>=120: continue
            tot+=abs(a[y][x]-b[yy][xx]);cnt+=1
    return tot/cnt
def classify(r,c,kind):
    a=sq_alpha(r,c,kind)
    ac=centroid(a,80)
