                for ddy in range(-2,3):
                    e=err(a,g,dx+ddx,dy+ddy)
                    if e<best[0]: best=(e,s,dx+ddx,dy+ddy)
        res.append((best[0],n,best[1]))
    res.sort()
    return res
for (r,c,k) in [(7,2,'white'),(3,6,'black'),(5,2,'white'),(3,3,'black'),(6,4,'white'),(7,4,'white'),(3,5,'black'),(0,2,'black'),(0,3,'black'),(2,2,'black'),(5,0,'white'),(3,4,'white'),(6,6,'white')]:
    res=classify(r,c,k)
    print(f"r{r}c{c} {k}: "+"  ".join(f"{n}:{e:.3f}@s{s}" for e,n,s in res))
